create extension if not exists pgcrypto;
create type ride_status as enum ('SEARCHING','OFFERS_AVAILABLE','DRIVER_SELECTED','DRIVER_ARRIVING','DRIVER_ARRIVED','RIDE_STARTED','RIDE_COMPLETED','PAYMENT_PENDING','PAYMENT_SUCCESS','CANCELLED','EXPIRED');
create type driver_status as enum ('PENDING','APPROVED','REJECTED','SUSPENDED');
create type offer_status as enum ('pending','accepted_by_passenger','rejected','expired','withdrawn');
create table profiles(id uuid primary key,user_id uuid unique not null,full_name text,avatar_url text,role text not null default 'PASSENGER',rating numeric(2,1) default 5,created_at timestamptz not null default now());
create table driver_profiles(id uuid primary key default gen_random_uuid(),user_id uuid unique not null,status driver_status not null default 'PENDING',birth_date date,license_number text,completed_rides int not null default 0,cancellation_rate numeric(5,2) not null default 0,created_at timestamptz not null default now());
create table vehicles(id uuid primary key default gen_random_uuid(),driver_id uuid not null references driver_profiles(id) on delete cascade,brand text not null,model text not null,year int,color text,plate_number text not null,vehicle_type text not null default 'STANDARD',photo_url text,status text not null default 'ACTIVE');
create table rides(id uuid primary key default gen_random_uuid(),passenger_id uuid not null,selected_driver_id uuid references driver_profiles(id),status ride_status not null default 'SEARCHING',pickup_lat double precision not null,pickup_lng double precision not null,pickup_address text,destination_lat double precision not null,destination_lng double precision not null,destination_address text,proposed_price bigint not null,final_price bigint,passenger_count int not null default 1,comment text,luggage boolean not null default false,vehicle_category text not null default 'STANDARD',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table ride_offers(id uuid primary key default gen_random_uuid(),ride_id uuid not null references rides(id) on delete cascade,driver_id uuid not null references driver_profiles(id) on delete cascade,price bigint not null,status offer_status not null default 'pending',created_at timestamptz not null default now(),expires_at timestamptz not null);
create unique index ride_offer_driver_unique on ride_offers(ride_id,driver_id) where status='pending';
create table driver_locations(driver_id uuid primary key references driver_profiles(id) on delete cascade,latitude double precision not null,longitude double precision not null,accuracy double precision,heading double precision,speed double precision,updated_at timestamptz not null default now());
create table payments(id uuid primary key default gen_random_uuid(),ride_id uuid unique not null references rides(id),passenger_id uuid not null,amount bigint not null,currency text not null default 'UZS',provider text not null default 'inPAY',provider_order_id text unique,provider_transaction_id text,status text not null default 'pending',created_at timestamptz not null default now(),paid_at timestamptz);
create table payment_events(id uuid primary key default gen_random_uuid(),payment_id uuid references payments(id),provider_event_id text unique,raw_status text,amount bigint,created_at timestamptz not null default now());
create table ratings(id uuid primary key default gen_random_uuid(),ride_id uuid not null references rides(id),from_user_id uuid not null,to_user_id uuid not null,stars int not null check(stars between 1 and 5),review text,created_at timestamptz not null default now(),unique(ride_id,from_user_id));
create table notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null,title text not null,body text not null,data jsonb not null default '{}',read_at timestamptz,created_at timestamptz not null default now());
create table support_tickets(id uuid primary key default gen_random_uuid(),user_id uuid not null,ride_id uuid references rides(id),category text not null,message text not null,status text not null default 'OPEN',created_at timestamptz not null default now(),resolved_at timestamptz);
create table reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null,reported_user_id uuid not null,ride_id uuid references rides(id),category text not null,message text,created_at timestamptz not null default now());
create table platform_settings(key text primary key,value jsonb not null,updated_at timestamptz not null default now());
create index rides_status_created on rides(status,created_at desc); create index offers_ride_expiry on ride_offers(ride_id,expires_at); create index driver_locations_updated on driver_locations(updated_at); create index payments_status on payments(status);
alter table profiles enable row level security; alter table driver_profiles enable row level security; alter table vehicles enable row level security; alter table rides enable row level security; alter table ride_offers enable row level security; alter table driver_locations enable row level security; alter table payments enable row level security; alter table ratings enable row level security; alter table notifications enable row level security; alter table support_tickets enable row level security; alter table reports enable row level security;